using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapTunnels.EditorTools;
public static class Spoil141Field{
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence141Mine");
 static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
 public static void Run(){Directory.CreateDirectory(Out);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.06f,.065f,.075f);var result=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"CutRock131");Check(result.built,"formal product tunnel build "+result.message);
 var camera=new GameObject("review camera").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.03f,.04f);camera.fieldOfView=45;camera.nearClipPlane=.03f;var hero=new GameObject("position gauge").transform;hero.position=new Vector3(12,0,11.4f);var cut=result.root.GetComponent<MapTunnels.MapTunnelCutaway>();cut.hero=hero;cut.viewCamera=camera;
 var rails=new GameObject("Formal rail prefabs");for(int j=0;j<2;j++){var o=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported125-valid/small-mine_rail_straight.prefab"));o.transform.SetParent(rails.transform,false);o.transform.position=new Vector3(12,0,14-j*2);}
 var cart=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported125-valid/small-minecart.prefab"));cart.transform.SetParent(rails.transform,false);cart.transform.position=new Vector3(12,.14f,13.4f);
 var rock=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported141-valid/small-mine_spoil.prefab"));rock.transform.SetParent(rails.transform,false);rock.transform.SetPositionAndRotation(new Vector3(12.92f,0,11.13f),Quaternion.Euler(0,90,0));rock.transform.localScale=Vector3.one*.25f;Physics.SyncTransforms();var rc=rock.GetComponent<MeshCollider>();Check(rc&&rc.bounds.min.x>12.60f,"soil collider leaves central rail/cart corridor");Check(!rc.bounds.Intersects(cart.GetComponent<Collider>().bounds),"cart corridor stays clear");Check(Mathf.Abs(rock.GetComponent<Renderer>().bounds.min.y)<1e-5,"soil contacts floor");var rockTarget=rock.GetComponent<Renderer>().bounds.center;
 // Existing authored tunnel lights only. Normal distance mirrors the game's overhead camera offset.
 foreach(string view in new[]{"before-normal","normal","close","reverse"}){rock.SetActive(view!="before-normal");camera.transform.position=(view=="normal"||view=="before-normal"?hero.position:rockTarget)+(view=="normal"||view=="before-normal"?new Vector3(0,9,-6.3f):view=="close"?new Vector3(-.7f,.55f,-.7f):new Vector3(-.7f,.55f,.7f));camera.transform.LookAt(view=="normal"||view=="before-normal"?hero.position+Vector3.up*.5f:rockTarget);typeof(MapTunnels.MapTunnelCutaway).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cut,null);var image=Shared117Review.Image(camera,1600,900);File.WriteAllBytes(Path.Combine(Out,view+".png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}
 var save=PrefabUtility.SaveAsPrefabAsset(rails,"Assets/Imported141-valid/mine-spoil-placement.prefab");UnityEngine.Object.DestroyImmediate(rails);rails=(GameObject)PrefabUtility.InstantiatePrefab(save);Check(rails.GetComponentsInChildren<Renderer>().All(r=>r.sharedMaterial.GetColor("_BaseColor")==Color.white),"persistent tint after previous Editor exit and prefab reload");
 File.WriteAllText(Path.Combine(Out,"checks.json"),"{\"pass\":true,\"source\":\"Product mine tunnel generator: 14m line, width2.4m, height2.8m, terrain3.5m\",\"formalTunnelImporter\":true,\"formalRailPrefabs\":2,\"formalSpoilPrefab\":true,\"centralCorridorClear\":true,\"existingLights\":"+result.lights+",\"originalGameSceneChanged\":false,\"player\":false,\"limitation\":\"Authored product mine test map. Soil scale0.25 beside 2.4m-wide rail corridor; full-size mound belongs in wider alcoves. Separate actual game cave review retained.\"}");AssetDatabase.SaveAssets();EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
